/**
 * Escapes `<`, `>`, `{` and `}` inside code fences and inline code within an `<MDX>` body, so code
 * there needs no hand-escaping and parses exactly like code at the page root.
 *
 * The body of an `<MDX>` inside a `{…}` expression is JSX text to the MDX parser: a raw `<` starts
 * a tag and a raw `{` starts an expression, so ``​`mint <cmd>`​`` or a fence containing
 * `<project-root>` fails the whole page with "Could not parse expression with acorn" — a code
 * fence gives no protection because it only becomes code later, when `remarkMdxExpandExpressions`
 * re-parses the body as markdown. This pass rewrites those characters to character references
 * (valid JSX text) before any MDX parse; `remarkMdxExpandExpressions` decodes them
 * (`decodeMdxFragmentCode`) once the body has been parsed and the code content is safely inside
 * `code`/`inlineCode` nodes.
 *
 * Runs as a string pass alongside `preprocessCustomHeadingIds`, with the same line scan and fence
 * tracking: content inside a page-level fence is never touched (an `<MDX>` there is example code),
 * and prose/JSX inside an `<MDX>` body is left alone — only fence content and inline code spans
 * are rewritten, including spans on the same line as the `<MDX>` tags. Block-level `<MDX>` bodies
 * get the same treatment so both forms behave identically; their code nodes are decoded by the
 * same plugin. Constructs the line scan cannot see — an inline code span or an opening tag
 * spanning lines, a span whose content contains backticks — are left alone and fail open: the
 * page parses (or fails) exactly as it did before this pass existed, and nothing is corrupted.
 *
 * The pass is idempotent (nothing it emits is rewritten again), so stacked parse entries — e.g.
 * prebuild normalizing a page that `getMdx` later compiles, or a fragment re-parse hitting
 * `getAST` — are safe by construction, and a fragment sliced out of its `<MDX>` tags no longer
 * matches the scanner at all.
 */
export declare function preprocessMdxFragmentCode(content: string): string;
/**
 * Inverse of the escape above, applied by `remarkMdxExpandExpressions` to `code`/`inlineCode`
 * node values inside `<MDX>`. Decodes exactly the references the escape emits plus `&amp;`, which
 * makes hand-written references work the way JSX text says they should (`&lt;` is `<`) and keeps
 * every literal spellable (`&amp;lt;` is a literal `&lt;`). Single-pass, so decoded output is
 * never re-decoded.
 */
export declare const decodeMdxFragmentCode: (value: string) => string;
